    pascal = [[0 for _ in range(m+1)] for _ in range(n+1)]

    # Fill the Pascal's triangle
    for i in range(n+1):
        pascal[i][0] = pascal[i][i] = 1
        for j in range(1, i):
            pascal[i][j] = (pascal[i-1][j-1] + pascal[i-1][j]) % mod

    # Compute the combinations with repetitions problem
    grid = [[0 for _ in range(n+1)] for _ in range(m+1)]
    for i in range(n+1):
        grid[i][0] = (i * (i + 1) // 2) % mod

    for i in range(1, m+1):
        for j in range(1, n+1):
            grid[i][j] = (a[j-1] * grid[i-1][j]) % mod
            grid[i][j] = (grid[i][j] + grid[i][j-1]) % mod

    return (pascal[n][m] * grid[m][n]) % mod

