        if perm[i] < perm[i + 1]:
            # Find the smallest element that is larger and comes after it
            for j in range(len(perm) - 1, i, -1):
                if perm[j] > perm[i]:
                    # Swap the elements
                    perm[i], perm[j] = perm[j], perm[i]
